<script setup>
import {ref,computed,watch} from 'vue';import {ReplayIndex} from '../replay.js';
const props=defineProps({journal:Object});const cursor=ref(0);watch(()=>props.journal,()=>{cursor.value=0});
const index=computed(()=>{try{return new ReplayIndex(props.journal)}catch{return null}});
const state=computed(()=>{try{return index.value?.seek(Number(cursor.value)).drill.view()??null}catch{return null}});
const visibleCue = computed(() => state.value?.recall ? state.value.recall.index : state.value?.cue?.index);
const event=computed(()=>props.journal.events[Number(cursor.value)-1]);
</script><template><section class="event-replay" v-if="state"><div class="replay-top"><b>交互回放</b><span>{{(state.elapsed/1000).toFixed(2)}} s · {{cursor}} / {{journal.events.length}}</span></div><svg viewBox="0 0 400 110" aria-label="回放中的五个交互目标"><line x1="35" y1="53" x2="365" y2="53" stroke="#42627e"/><g v-for="i in 5" :key="i"><circle :cx="40+(i-1)*80" cy="53" :r="visibleCue===i-1?23:16" :fill="visibleCue===i-1?(state.cue.avoid?'#b85a49':'#b3d9e5'):'#203b54'" :stroke="visibleCue===i-1?'#d6edf5':'#52738c'"/><text :x="40+(i-1)*80" y="58" text-anchor="middle" :fill="visibleCue===i-1?'#18344c':'#b6d0e5'" font-size="12">{{i}}</text></g></svg><p v-if="state.recall">{{state.recall.phase === 'ready' ? '准备观察' : state.recall.phase === 'watch' ? '观察第 '+(state.recall.step+1)+' 个' : '已按序复现 '+state.recall.step+' / '+state.recall.count}}</p><input type="range" aria-label="选择回放事件" min="0" :max="journal.events.length" step="1" v-model.number="cursor"><div class="replay-controls"><button type="button" :disabled="cursor===0" @click="cursor--">上一事件</button><button type="button" :disabled="cursor>=journal.events.length" @click="cursor++">下一事件</button><span>命中 {{state.hits}} · 误选 {{state.mistakes}} · 漏过 {{state.missed}}</span></div><p>{{event?(event[1]==='t'?(event[3]<0?'时间推进 / 未指向目标':'时间推进 / 指向目标 '+(event[3]+1)):'输入目标 '+(event[2]+1)+' '+event[3]):'训练起点'}}<br>目标交互状态回放，不包含人体姿势或头显运动轨迹。</p></section></template><style scoped>.event-replay{margin:18px 0;padding:15px;background:#142c43;border:1px solid #385570;border-radius:3px}.replay-top{display:flex;justify-content:space-between;font-size:11px;color:#c8dfed}.replay-top>span{font:10px monospace;color:#91afc6}.event-replay svg{width:100%;display:block;max-height:120px}.event-replay input{display:block;width:100%;margin:0!important;accent-color:#b3d9e5}.replay-controls{display:flex;gap:7px;align-items:center;margin-top:12px}.replay-controls>span{margin-left:auto;font-size:10px;color:#9fbad0}.event-replay button{padding:6px 8px!important;background:#203b54!important;color:#c8e2ed!important;border-color:#426482!important;font-size:10px!important}.event-replay p{font-size:10px!important;color:#9fbad0!important;margin:12px 0 0;line-height:1.7}</style>
